'use client'

import { useMemo, useState } from 'react'
import { LANGS, LANGUAGE_NAMES, useLang, type Key, type Lang, type Localized } from '@/lib/i18n'
import { DISTRICTS, MAHARASHTRA_TOTALS, PATIENTS, PATIENT_DETAILS, type Band } from '@/lib/maharashtra'
import { speak, stopSpeaking } from '@/lib/speech'
import {
  Activity, AlertTriangle, ArrowLeft, ArrowRight, BarChart3, Battery, Bluetooth, Check, ChevronDown,
  Cloud, Download, FileText, HeartPulse, Home, Languages, LineChart, LogOut, MapPin, Menu, Moon, Play, Plus,
  Printer, Search, Send, Settings, ShieldCheck, Sparkles, Stethoscope, TabletSmartphone, UserRound, Users,
  Wifi, X,
} from 'lucide-react'

// Internal enum values (risk, status, pain, referral status, occupation slug, district id) are kept as-is in data
// and translated only at render time through the helpers exposed by useLang().
type Risk = 'Low' | 'Moderate' | 'High'
type Patient = { name: string; sex: string; nameL: Localized; age: number; village: string; villageL: Localized; district: string; occupation: string; score: number; risk: Risk; rom: string; gait: string; pain: string; status: string }
const seedPatients: Patient[] = PATIENTS.map((patient) => ({ name: patient.name.en, sex: patient.sex === 'F' ? 'Female' : 'Male', nameL: patient.name, age: patient.age, village: patient.village.en, villageL: patient.village, district: patient.district, occupation: patient.occupation, score: patient.score, risk: patient.risk, rom: patient.rom, gait: patient.gait, pain: patient.pain, status: patient.status }))
const steps: Key[] = ['stepPatient', 'stepHistory', 'stepPain', 'stepMotion', 'stepAI', 'stepResult', 'stepCarePlan']
const riskClass = (risk: string) => risk === 'High' ? 'risk-high' : risk === 'Moderate' ? 'risk-moderate' : 'risk-low'
const districtAllNames = (id: string) => { const d = DISTRICTS.find((item) => item.id === id); return d ? `${d.name.en} ${d.name.hi} ${d.name.mr}` : id }
/** Searchable text in every language, so a query typed in any script matches. */
const nameText = (x: Patient) => `${x.name} ${x.nameL.hi} ${x.nameL.mr}`
const searchText = (x: Patient) => `${nameText(x)} ${x.village} ${x.villageL.hi} ${x.villageL.mr} ${districtAllNames(x.district)}`.toLowerCase()
const nameDistrictText = (x: Patient) => `${nameText(x)} ${districtAllNames(x.district)}`.toLowerCase()
const firstName = (value: string) => value.split(' ')[0]

function Brand({ compact = false }: { compact?: boolean }) { const { t } = useLang(); return <div className="brand"><div className="brand-mark"><HeartPulse size={22} /></div><div><strong>ArthroFlex</strong>{!compact && <small>{t('brandSubtitle')}</small>}</div></div> }
function Card({ children, className = '' }: { children: React.ReactNode; className?: string }) { return <section className={`card ${className}`}>{children}</section> }
function Badge({ children, risk }: { children: React.ReactNode; risk?: string }) { return <span className={`badge ${risk ? riskClass(risk) : ''}`}>{children}</span> }
function Toast({ message }: { message: string }) { return message ? <div className="toast"><Check size={16} /> {message}</div> : null }
function LanguageMenu() { const { lang, setLang, t } = useLang(); return <label className="language-menu"><Languages size={15} aria-hidden="true" /><span className="sr-only">{t('selectLanguage')}</span><select aria-label={t('selectLanguage')} value={lang} onChange={(event) => setLang(event.target.value as Lang)}>{LANGS.map((item) => <option key={item} value={item}>{LANGUAGE_NAMES[item]}</option>)}</select></label> }

export default function Page() {
  const { t } = useLang()
  const [role, setRole] = useState<'field' | 'doctor' | null>(null)
  const [section, setSection] = useState('Overview')
  const [step, setStep] = useState(0)
  const [patients, setPatients] = useState(seedPatients)
  const [completedToday, setCompletedToday] = useState(12)
  const [selected, setSelected] = useState<Patient | null>(seedPatients[0] ?? null)
  const [reportOpen, setReportOpen] = useState(false)
  const [reportName, setReportName] = useState('')
  const [toast, setToast] = useState('')
  const [syncing, setSyncing] = useState(false)
  const [sensor, setSensor] = useState('Connected')
  const [height, setHeight] = useState('158')
  const [weight, setWeight] = useState('68')
  const [logoutOpen, setLogoutOpen] = useState(false)
  const [fieldMenuOpen, setFieldMenuOpen] = useState(false)
  const [doctorMenuOpen, setDoctorMenuOpen] = useState(false)
  const [referrals, setReferrals] = useState(() => seedPatients.filter((patient) => patient.risk === 'High').map((patient, index) => ({ ...patient, referralStatus: index === 0 ? 'Pending' : 'In review' })))
  const bmi = useMemo(() => Math.round((Number(weight) / ((Number(height) / 100) ** 2)) * 10) / 10, [height, weight])
  const notify = (message: string) => { setToast(message); window.setTimeout(() => setToast(''), 2500) }
  const requestLogout = () => setLogoutOpen(true)
  const completeLogout = () => { setLogoutOpen(false); setRole(null); setSection('Overview'); setStep(0); setSelected(null); setFieldMenuOpen(false); setDoctorMenuOpen(false); setToast('') }
  if (!role) return <Welcome onChoose={setRole} />
  const field = role === 'field'
  return <div className={`app-shell ${field ? 'field-shell' : 'portal-shell'}`}>
    <header className="topbar"><Brand /><div className="topbar-right"><span className="demo-pill"><span className="live-dot" /> {t('prototypeWorkspace')}</span><LanguageMenu /><button className="icon-button" aria-label={t('theme')} onClick={() => notify(t('themeSettings'))}><Moon size={17} /></button><button className="avatar" onClick={requestLogout}>{field ? t('initialsWorker') : t('initialsDoctor')}</button></div></header>
    {field ? <FieldApp {...{ section, setSection, step, setStep, patients, setPatients, syncing, setSyncing, sensor, setSensor, height, setHeight, weight, setWeight, bmi, completedToday, setCompletedToday, notify, requestLogout, fieldMenuOpen, setFieldMenuOpen, reportOpen, setReportOpen, reportName, setReportName, selected, setSelected }} /> : <PortalApp section={section} setSection={setSection} selected={selected} setSelected={setSelected} patients={patients} referrals={referrals} setReferrals={setReferrals} notify={notify} requestLogout={requestLogout} doctorMenuOpen={doctorMenuOpen} setDoctorMenuOpen={setDoctorMenuOpen} />}
    <Toast message={toast} />
    {logoutOpen && <LogoutDialog onCancel={() => setLogoutOpen(false)} onConfirm={completeLogout} />}
  </div>
}

function Welcome({ onChoose }: { onChoose: (role: 'field' | 'doctor') => void }) { const { lang, setLang, t } = useLang(); return <main className="welcome"><div className="language-switcher" aria-label={t('language')}>{LANGS.map((item) => <button key={item} className={lang === item ? 'active' : ''} onClick={() => setLang(item)}>{LANGUAGE_NAMES[item]}</button>)}</div><div className="welcome-grid"><div className="welcome-copy"><Brand /><h1>{t('welcomeHeadline')}<br /><span>{t('welcomeHeadlineAccent')}</span></h1><p>{t('ruralMaharashtra')}</p><div className="trust-row"><ShieldCheck size={18} /> {t('fiction')}</div></div><div className="role-panel"><div className="panel-kicker">{t('welcome')}</div><h2>{t('chooseRole')}</h2><p className="muted">{t('fiction')}</p><div className="role-list"><button onClick={() => onChoose('field')} className="role-card"><div className="role-icon teal"><TabletSmartphone /></div><div><strong>{t('fieldWorker')}</strong><span>{t('conduct')}</span></div><ArrowRight /></button><button onClick={() => onChoose('doctor')} className="role-card"><div className="role-icon blue"><Stethoscope /></div><div><strong>{t('doctor')}</strong><span>{t('review')}</span></div><ArrowRight /></button></div><div className="privacy-note"><ShieldCheck size={15} /> {t('fiction')}</div></div></div></main> }

function FieldApp(p: any) { const { t } = useLang(); const nav = [{ n: 'Overview', label: t('overview'), i: Home }, { n: 'Patients', label: t('patients'), i: Users }, { n: 'New Screening', label: t('newScreening'), i: Plus }, { n: 'Sync Center', label: t('syncCenter'), i: Cloud }, { n: 'Profile', label: t('profile'), i: UserRound }]; const sync = () => { p.setSyncing(true); window.setTimeout(() => { p.setSyncing(false); p.notify(t('allRecordsSynced')) }, 1600) }; return <><aside className={`field-sidebar ${p.fieldMenuOpen ? 'mobile-open' : ''}`}><Brand compact /><div className="worker-card"><div className="worker-avatar">{t('initialsWorker')}</div><div><strong>{t('workerName')}</strong><span>{t('workerRole')}</span></div></div><nav>{nav.map(({ n, label, i: I }) => <button key={n} className={p.section === n ? 'active' : ''} onClick={() => { n === 'New Screening' ? (p.setSection(n), p.setStep(0)) : p.setSection(n); p.setFieldMenuOpen(false) }}><I size={18} /><span>{label}</span>{n === 'Sync Center' && <b>3</b>}</button>)}</nav><div className="offline-card"><div><span className="live-dot" /> {t('offlineReady')}</div><small>{t('lastSync')}</small><button onClick={sync}>{p.syncing ? t('syncing') : t('syncNow')} <Cloud size={14} /></button></div><div className="menu-footer"><button onClick={() => p.notify(t('settingsOpened'))}><Settings size={18} /><span>{t('settings')}</span></button><button className="logout-link" onClick={p.requestLogout}><LogOut size={18} /><span>{t('logout')}</span></button></div></aside><main className="field-main">{p.fieldMenuOpen && <button className="mobile-backdrop" aria-label={t('closeMenu')} onClick={() => p.setFieldMenuOpen(false)} /> }<div className="mobile-header"><button className="menu-trigger" aria-label={t('openMenu')} onClick={() => p.setFieldMenuOpen((open: boolean) => !open)}><Menu /></button><Brand compact /><div className="avatar">{t('initialsWorker')}</div></div>{p.section === 'New Screening' ? <Screening {...p} patient={p.selected ?? seedPatients[0]} /> : p.section === 'Patients' ? <Patients {...p} /> : p.section === 'Sync Center' ? <SyncCenter {...p} onSync={sync} /> : p.section === 'Profile' ? <Profile {...p} /> : <FieldHome {...p} onStart={() => { p.setSection('New Screening'); p.setStep(0) }} onSync={sync} />}</main></> }

function LogoutDialog({ onCancel, onConfirm }: { onCancel: () => void; onConfirm: () => void }) { const { t } = useLang(); return <div className="dialog-backdrop" role="presentation"><section className="logout-dialog" role="dialog" aria-modal="true" aria-labelledby="logout-title"><div className="dialog-icon"><LogOut size={20} /></div><h2 id="logout-title">{t('logoutTitle')}</h2><p>{t('logoutConfirmText')}</p><div className="dialog-actions"><button className="outline-button" onClick={onCancel}>{t('cancel')}</button><button className="primary-button logout-confirm" onClick={onConfirm}>{t('logout')} <LogOut size={16} /></button></div></section></div> }
function FieldHome(p: any) { const { t } = useLang(); return <div className="content"><div className="page-heading"><div><span className="eyebrow">{t('mondayDate')}</span><h1>{t('goodMorning')}</h1><p className="muted">{t('fieldHomeDescription')}</p></div><LanguageMenu /></div><Card className="hero-card"><div><span className="eyebrow light">{t('todayFocus')}</span><h2>{t('screenOneMore')}<br />{t('healthierKnees')}</h2><p>{t('guidedCheck')}</p><button className="primary-button" onClick={p.onStart}>{t('startScreening')} <ArrowRight size={17} /></button></div><div className="hero-art"><div className="joint-orbit"><HeartPulse size={54} /></div><div className="art-label">{t('tenSec')}<br /><small>{t('motionCheck')}</small></div></div></Card><div className="section-title"><h2>{t('todaysActivity')}</h2><button className="text-button" onClick={() => p.setSection('Patients')}>{t('viewRecords')} <ArrowRight size={15} /></button></div><div className="stat-grid"><Card><span className="stat-label">{t('patientsScreened')}</span><strong>{p.completedToday}</strong><small className="positive">{t('fromYesterday')}</small></Card><Card><span className="stat-label">{t('needsAttention')}</span><strong className="amber-text">{p.patients.filter((x: Patient) => x.risk === 'High').length}</strong><small>{t('highRiskCases')}</small></Card><Card><span className="stat-label">{t('waitingToSync')}</span><strong>3</strong><small>{t('savedOnDevice')}</small><button className="small-action" onClick={p.onSync}><Cloud size={14} /> {t('syncNow')}</button></Card></div></div> }

function Screening(p: any) { const { t } = useLang(); return <div className="content screening"><div className="screening-top"><button className="back-button" onClick={() => p.step === 0 ? p.setSection('Overview') : p.setStep(p.step - 1)}><ArrowLeft size={16} /> {t('back')}</button><span className="demo-pill"><span className="live-dot" /> {t('offlineMode')}</span></div><div className={`screening-frame ${[0, 1, 2, 5].includes(p.step) ? 'aligned' : ''}`}><div className="stepper">{steps.map((s, i: number) => <div className={`step ${i <= p.step ? 'done' : ''}`} key={s}><span>{i < p.step ? <Check size={12} /> : i + 1}</span><small>{t(s)}</small></div>)}</div>{p.step === 0 ? <Registration {...p} /> : p.step === 1 ? <History {...p} /> : p.step === 2 ? <Questionnaire {...p} /> : p.step === 3 ? <Motion {...p} /> : p.step === 4 ? <Analysis {...p} /> : p.step === 5 ? <Result {...p} /> : <CarePlan {...p} />}</div></div> }
function StepHead({ kicker, title, copy }: any) { return <div className="step-head"><span className="eyebrow">{kicker}</span><h1>{title}</h1><p className="muted">{copy}</p></div> }
function Next({ onClick, children }: any) { const { t } = useLang(); return <button className="primary-button next-button" onClick={onClick}>{children ?? t('continueBtn')} <ArrowRight size={17} /></button> }
function Registration(p: any) { const { t, sex, district } = useLang(); return <><StepHead kicker={t('step1Kicker')} title={t('step1Title')} copy={t('step1Copy')} /><div className="screening-container"><Card className="form-card"><div className="form-grid"><label>{t('patientName')}<input defaultValue="Sushila Jadhav" /></label><label>{t('age')}<input type="number" defaultValue="62" /></label><label>{t('biologicalSex')}<select defaultValue="Female">{['Female', 'Male', 'Other'].map((x) => <option key={x} value={x}>{sex(x)}</option>)}</select></label><label>{t('phoneNumber')}<input defaultValue="+91 98765 43210" /></label><label>{t('villageLocality')}<input defaultValue="Georai" /></label><label>{t('district')}<select defaultValue="beed">{DISTRICTS.map((d) => <option key={d.id} value={d.id}>{district(d.id)}</option>)}</select></label><label>{t('heightCm')}<input value={p.height} onChange={(e: any) => p.setHeight(e.target.value)} /></label><label>{t('weightKg')}<input value={p.weight} onChange={(e: any) => p.setWeight(e.target.value)} /></label></div><div className="bmi-box"><Activity size={20} /><div><span>{t('bmiAuto')}</span><strong>{p.bmi} <small>{p.bmi >= 25 ? t('bmiHigh') : t('bmiHealthy')}</small></strong></div></div><div className="form-footer"><button className="outline-button" onClick={() => p.notify(t('existingPatientOpened'))}><Search size={16} /> {t('useExistingPatient')}</button><Next onClick={() => p.setStep(1)} /></div></Card></div></> }
function History(p: any) { const { t, tf, L, occupation } = useLang(); const options = ['farm-labourer', 'sugarcane-cutter', 'farmer', 'forest-gatherer', 'construction-worker', 'homemaker']; return <><StepHead kicker={t('step2Kicker')} title={t('step2Title')} copy={tf('step2Copy', { name: firstName(L((p.patient ?? seedPatients[0]).nameL)) })} /><div className="screening-container"><Card className="question-card"><span className="question-label">{t('primaryOccupation')}</span><div className="choice-grid">{options.map((x, i) => <button key={x} className={i === 0 ? 'choice selected' : 'choice'} onClick={(e: any) => { e.currentTarget.parentElement.querySelectorAll('button').forEach((b: HTMLElement) => b.classList.remove('selected')); e.currentTarget.classList.add('selected') }}>{occupation(x)}{i === 0 && <Check size={15} />}</button>)}</div><div className="divider" /><div className="quick-questions"><div><span>{t('squattingPerDay')}</span><strong>{t('moreThan2Hours')} <ChevronDown size={15} /></strong></div><div><span>{t('morningStiffness')}</span><strong>{t('moreThan30Min')} <ChevronDown size={15} /></strong></div><div><span>{t('previousInjury')}</span><strong>{t('no')} <ChevronDown size={15} /></strong></div></div></Card><Next onClick={() => p.setStep(2)} /></div></> }
function Questionnaire(p: any) { const { lang, setLang, t, pain } = useLang(); const [answer, setAnswer] = useState('Severe'); const [audio, setAudio] = useState(false); const [missing, setMissing] = useState(false); const question = t('painQuestion'); const levels = ['No pain', 'Mild', 'Moderate', 'Severe', 'Extreme']; const play = () => { setMissing(false); speak(question, lang, () => setAudio(true), () => setAudio(false), () => { setAudio(false); setMissing(true) }) }; return <><StepHead kicker={t('step3Kicker')} title={t('step3Title')} copy={t('step3Copy')} /><div className="screening-container"><Card className="question-card audio-card"><h2>{question}</h2><button className="audio-button" onClick={audio ? stopSpeaking : play}><Play size={15} fill="currentColor" /> {audio ? t('stop') : t('playQuestion')} <span>{LANGUAGE_NAMES[lang]}</span></button>{missing && <small className="muted">{t('voiceMissing')}</small>}<div className="pain-options">{levels.map((value) => <button className={answer === value ? 'pain selected' : 'pain'} key={value} onClick={() => setAnswer(value)}>{pain(value)}{answer === value && <Check size={16} />}</button>)}</div><button className="language-row" onClick={() => setLang(lang === 'en' ? 'hi' : lang === 'hi' ? 'mr' : 'en')}><Languages size={16} /> {t('language')}: <strong>{lang === 'en' ? t('english') : lang === 'hi' ? t('hindi') : t('marathi')}</strong> <ChevronDown size={14} /></button></Card><Next onClick={() => p.setStep(3)}>{t('continueMotion')}</Next></div></> }
function Motion(p: any) { const { t, sensor } = useLang(); const [running, setRunning] = useState(false); return <><StepHead kicker={t('step4Kicker')} title={t('step4Title')} copy={t('step4Copy')} /><div className="motion-layout"><Card className="sensor-card"><div className="sensor-status"><span className="live-dot" /> ESP32 + MPU6050 <Badge>{running ? t('active') : sensor(p.sensor)}</Badge></div><div className="sensor-status video-status"><span className="live-dot" /> {t('videoAnalysis')} <Badge>{running ? t('cameraActive') : t('ready')}</Badge></div><div className="knee-visual"><div className="knee-ring"><Activity size={54} /></div><div className="motion-instruction">{running ? t('assessmentRunning') : t('performBends')}<small>{running ? t('capturingMovement') : t('sensorReadyCapture')}</small></div></div><div className="sensor-metrics"><div><span>BLE</span><strong><Bluetooth size={14} /> {t('connected')}</strong></div><div><span>{t('sampling')}</span><strong>100 Hz</strong></div><div><span>{t('battery')}</span><strong><Battery size={14} /> 84%</strong></div><div><span>{t('signal')}</span><strong className="positive">{t('excellent')}</strong></div></div><button className="primary-button full" disabled={running} onClick={() => { setRunning(true); p.setSensor('Measuring'); window.setTimeout(() => { setRunning(false); p.setSensor('Connected'); p.setStep(4) }, 2200) }}><Play size={16} fill="currentColor" /> {running ? t('measuring') : t('beginAssessment')}</button><div className="assessment-note"><TabletSmartphone size={16} /> {t('sensorCameraActive')}</div></Card><Card className="metrics-card"><span className="eyebrow">{t('liveReadings')}</span><h3>{t('kneeKinematics')}</h3><div className="reading-grid"><div><span>{t('maxFlexion')}</span><strong>118°</strong></div><div><span>{t('extension')}</span><strong>4°</strong></div><div><span>{t('symmetry')}</span><strong>87%</strong></div><div><span>{t('smoothness')}</span><strong>{t('good')}</strong></div></div><div className="reading-section"><h3>{t('videoAnalysis')} <small>{t('cameraPose')}</small></h3><div className="reading-grid"><div><span>{t('kneeFlexionAngle')}</span><strong>116°</strong></div><div><span>{t('gaitSymmetry')}</span><strong>82%</strong></div><div><span>{t('movementConsistency')}</span><strong>{t('good')}</strong></div><div><span>{t('poseConfidence')}</span><strong>94%</strong></div></div></div></Card></div></> }
function Analysis(p: any) { const { t } = useLang(); const [done, setDone] = useState(false); return <Card className="analysis-card"><div className="analysis-orb"><Sparkles size={48} /></div><span className="eyebrow">{t('aiScreening')}</span><h1>{t('readingFullPicture')}</h1><p className="muted">{t('combiningSignals')}</p><div className="analysis-list">{[t('patientHistory'), t('painMobility'), t('kneeMotion'), t('gaitPattern'), t('riskFactors')].map((x) => <div key={x} className="analysis-row"><span className="analysis-check"><Check size={13} /></span>{x}<span className="analysis-line"><i /></span><small>{t('analyzed')}</small></div>)}</div><button className="primary-button" onClick={() => { setDone(true); p.setStep(5) }}>{done ? t('analysisComplete') : t('viewScreeningResult')} <ArrowRight size={17} /></button><p className="tiny-note"><ShieldCheck size={13} /> {t('screeningIndicatorNote')}</p></Card> }
function Result(p: any) { const { t, tf, L } = useLang(); const patient: Patient = p.patient ?? seedPatients[0]; const factors: Array<[Key, string]> = [['factorPain', '24%'], ['factorROM', '18%'], ['factorGait', '11%'], ['factorOccupational', '6%']]; return <><StepHead kicker={t('step6Kicker')} title={tf('clearNextStep', { name: L(patient.nameL) })} copy={t('followUpFactors')} /><div className="screening-container"><Card className="result-card"><div className="result-top"><div className="gauge"><span>{patient.score}</span><small>/ 100</small></div><div><Badge risk="High">{t('highRiskUpper')}</Badge><h2>{t('elevatedRisk')}</h2><p>{t('clinicalEvaluation')}</p></div></div><div className="result-divider" /><section className="risk-contributors"><h3>{t('riskContributors')}</h3><div className="factor-grid">{factors.map(([x, v]) => <div className="factor" key={x}><span>{t(x)}</span><strong>{v}</strong><div className="progress-track"><i style={{ width: v }} /></div></div>)}</div></section><section className="marker-list"><strong>{t('keyMarkers')}</strong><div className="marker-grid"><span><Check /> {t('reducedFlexion')}</span><span><Check /> {t('mildGait')}</span><span><Check /> {t('morningStiffness')}</span><span><Check /> {t('squattingExposure')}</span></div></section></Card><div className="result-actions"><div className="result-actions-left"><button className="outline-button" onClick={() => p.notify(t('reportGenerated'))}>{t('generateReport')}</button><button className="outline-button" onClick={() => p.notify(t('referralCreated'))}>{t('generateReferral')}</button></div><Next onClick={() => p.setStep(6)}>{t('viewCarePlan')}</Next></div></div></> }
function CarePlan(p: any) { const { t, tf, L } = useLang(); const patient: Patient = p.patient ?? seedPatients[0]; const exercises: Key[] = ['exQuadSets', 'exLegRaises', 'exHeelSlides']; return <><StepHead kicker={t('step7Kicker')} title={tf('carePlanTitle', { name: L(patient.nameL) })} copy={t('carePlanCopy')} /><div className="care-grid"><Card><div className="card-heading"><div><span className="eyebrow">{t('movement')}</span><h3>{t('gentleExercises')}</h3></div><Activity /></div>{exercises.map((x, i) => <button className="exercise" key={x} onClick={() => p.notify(tf('exerciseDoseShort', { name: t(x) }))}><div className="exercise-icon">0{i + 1}</div><div><strong>{t(x)}</strong><span>{t('exerciseDose')}</span></div><ArrowRight size={15} /></button>)}</Card><Card><span className="eyebrow">{t('livelihoodErgonomics')}</span><h3>{t('farmerGuidanceTitle')}</h3><p className="care-copy">{t('farmerGuidance')}</p><div className="care-tip"><ShieldCheck size={16} /> {t('preventionGuidance')}</div><button className="primary-button full" onClick={() => { p.setPatients((old: Patient[]) => old.map((patient) => patient.name === 'Sushila Jadhav' ? { ...patient, status: 'Saved Offline', score: 84, risk: 'High' } : patient)); p.setCompletedToday((count: number) => count + 1); p.notify(t('screeningCompleted')); window.setTimeout(() => { p.setStep(0); p.setSection('Overview') }, 900) }}>{t('saveFinish')} <Check size={16} /></button></Card></div><Card className="delivery-card"><div><span className="eyebrow">{t('shareWithPatient')}</span><h3>{t('deliverCarePlan')}</h3></div><div className="delivery-actions"><button onClick={() => p.notify(t('carePlanSent'))}><Send size={18} /> {t('sendPhone')}</button><button onClick={() => p.notify(t('printableReady'))}><Printer size={18} /> {t('printSlip')}</button><button onClick={() => p.notify(t('reportGeneratedShort'))}><FileText size={18} /> {t('generateReport')}</button></div></Card></> }

function Patients(p: any) { const { t, tf, L, risk, district } = useLang(); const [query, setQuery] = useState(''); const [filter, setFilter] = useState('All'); const shown = p.patients.filter((x: Patient) => (filter === 'All' || x.risk === filter) && searchText(x).includes(query.toLowerCase())); if (p.reportOpen) return <PatientReport patient={p.patients.find((x: Patient) => x.name === p.reportName) ?? p.patients[0]} onBack={() => p.setReportOpen(false)} />; return <div className="content"><div className="page-heading"><div><span className="eyebrow">{tf('fieldRecordsTotal', { n: p.patients.length })}</span><h1>{t('patientsHeading')}</h1><p className="muted">{t('recordsSaved')}</p></div><button className="primary-button" onClick={() => { p.setSection('New Screening'); p.setStep(0) }}><Plus size={17} /> {t('newPatient')}</button></div><div className="search-row"><div className="search-box"><Search size={16} /><input placeholder={t('searchPatients')} aria-label={t('searchPatients')} value={query} onChange={(e) => setQuery(e.target.value)} /></div><select className="outline-button" aria-label={t('riskWord')} value={filter} onChange={(e) => setFilter(e.target.value)}><option value="All">{t('all')}</option><option value="Low">{risk('Low')}</option><option value="Moderate">{risk('Moderate')}</option><option value="High">{risk('High')}</option></select></div><div className="patient-list large">{shown.length ? shown.map((x: Patient) => <button className="patient-row" key={x.name} onClick={() => { p.setReportName(x.name); p.setReportOpen(true) }}><div className="patient-initial">{L(x.nameL).split(' ').map((s: string) => s[0]).join('')}</div><div className="patient-name"><strong>{L(x.nameL)}</strong><span>{tf('ageYears', { n: x.age })} · {L(x.villageL)}, {district(x.district)}</span></div><Badge risk={x.risk}>{risk(x.risk)}</Badge><strong className="score">{x.score}<small>/100</small></strong><ArrowRight size={16} /></button>) : <Card><h3>{t('noPatientsFound')}</h3><button className="outline-button" onClick={() => { setQuery(''); setFilter('All') }}>{t('clearFilters')}</button></Card>}</div></div> }

const SQUAT: Record<Band, Key> = { lt1h: 'lessThan1Hour', h1to2: 'oneToTwoHours', gt2h: 'moreThan2Hours', lt15: 'lessThan15Min', m15to30: 'min15to30', gt30: 'moreThan30Min' }
/** Display-only marker rules for the report; they do not feed any screening score. */
const reportMarkers = (patient: Patient): Key[] => { const d = PATIENT_DETAILS[patient.name]; return [parseInt(patient.rom) < 110 && 'reducedFlexion', parseInt(patient.gait) < 85 && 'mildGait', d?.stiffness === 'gt30' && 'morningStiffness', d?.squatting === 'gt2h' && 'squattingExposure'].filter(Boolean) as Key[] }
function PatientReport({ patient, onBack }: { patient: Patient; onBack: () => void }) {
  const { t, tf, L, riskPhrase, pain, sex, occupation, district, date } = useLang()
  const d = PATIENT_DETAILS[patient.name]; const occ = occupation(patient.occupation); const markers = reportMarkers(patient)
  const level = patient.risk === 'High' ? 'High' : patient.risk === 'Moderate' ? 'Moderate' : 'Low'
  const summary = { High: t('combinedRiskText'), Moderate: t('combinedRiskModerate'), Low: t('combinedRiskLow') }[level]
  const interpretation = { High: t('clinicalEvalShort'), Moderate: t('interpModerate'), Low: t('interpLow') }[level]
  const nextTitle = { High: t('referForEvaluation'), Moderate: t('nextModerate'), Low: t('nextLow') }[level]
  const nextCopy = { High: t('discussWithClinician'), Moderate: t('nextModerateCopy'), Low: t('nextLowCopy') }[level]
  return <div className="content report-page"><button className="back-button" onClick={onBack}><ArrowLeft size={16} /> {t('backToPatients')}</button><div className="page-heading report-heading"><div><span className="eyebrow">{t('screeningReport')}</span><h1>{L(patient.nameL)}</h1><p className="report-patient-meta">{tf('ageYears', { n: patient.age })} · {occ}</p><p className="muted">{tf('completedScreening', { date: d ? date(d.screeningDate) : '', place: `${L(patient.villageL)}, ${district(patient.district)}` })}</p></div><Badge risk={patient.risk}>{tf('riskScoreLine', { risk: riskPhrase(patient.risk).toUpperCase(), score: patient.score })}</Badge></div><div className="report-grid"><Card><span className="eyebrow">{t('patientScreeningSummary')}</span><div className="report-facts"><span>{t('age')}<strong>{tf('ageYears', { n: patient.age })}</strong></span><span>{t('biologicalSex')}<strong>{sex(patient.sex)}</strong></span><span>{t('bmi')}<strong>{d?.bmi.toFixed(1)}</strong></span><span>{t('occupation')}<strong>{occ}</strong></span></div></Card><Card><span className="eyebrow">{t('relevantRiskHistory')}</span><div className="report-list"><p>{t('primaryOccupation')} <strong>{occ}</strong></p><p>{t('squattingPerDay')} <strong>{d && t(SQUAT[d.squatting])}</strong></p><p>{t('morningStiffness')} <strong>{d && t(SQUAT[d.stiffness])}</strong></p><p>{t('previousInjury')} <strong>{d?.injury ? t('yes') : t('no')}</strong></p></div></Card><Card><span className="eyebrow">{t('painMobilityFindings')}</span><div className="report-list"><p>{t('painWhileWalking')} <strong className={patient.pain === 'Severe' || patient.pain === 'Extreme' ? 'risk-high-text' : ''}>{pain(patient.pain)}</strong></p><p>{t('maxFlexion')} <strong>{patient.rom}</strong></p><p>{t('gaitSymmetry')} <strong>{patient.gait}</strong></p></div></Card><Card><span className="eyebrow">{t('sensorKinematics')}</span><div className="report-facts"><span>ESP32 + MPU6050<strong>{t('captured')}</strong></span><span>{t('maxFlexion')}<strong>{d?.sensor.flexion}°</strong></span><span>{t('extension')}<strong>{d?.sensor.extension}°</strong></span><span>{t('symmetry')}<strong>{d?.sensor.symmetry}%</strong></span><span>{t('smoothness')}<strong>{d?.sensor.smoothness === 'Excellent' ? t('excellent') : t('good')}</strong></span></div></Card><Card><span className="eyebrow">{t('videoMediapipe')}</span><div className="report-facts"><span>{t('cameraAnalysis')}<strong>{t('captured')}</strong></span><span>{t('kneeFlexionAngle')}<strong>{d?.video.angle}°</strong></span><span>{t('gaitSymmetry')}<strong>{d?.video.gait}%</strong></span><span>{t('movementConsistency')}<strong>{d?.video.consistency === 'Excellent' ? t('excellent') : t('good')}</strong></span><span>{t('poseConfidence')}<strong>{d?.video.confidence}%</strong></span></div></Card><Card className="report-risk"><span className="eyebrow">{t('combinedRisk')}</span><div className="report-risk-line"><strong>{patient.score} <small>/ 100</small></strong><Badge risk={patient.risk}>{riskPhrase(patient.risk).toUpperCase()}</Badge></div><p>{summary}</p><div className="marker-grid">{markers.length ? markers.map((m) => <span key={m}><Check /> {t(m)}</span>) : <span>{t('noMarkers')}</span>}</div></Card></div><div className="report-bottom"><Card><span className="eyebrow">{t('clinicalInterpretation')}</span><h3>{interpretation}</h3><p className="muted">{t('decisionSupportNote')}</p></Card><Card><span className="eyebrow">{t('recommendedNextSteps')}</span><h3>{nextTitle}</h3><p className="muted">{nextCopy}</p></Card></div></div>
}
function SyncCenter(p: any) { const { t } = useLang(); return <div className="content"><div className="page-heading"><div><span className="eyebrow">{t('offlineFirst')}</span><h1>{t('syncCenterTitle')}</h1><p className="muted">{t('workStaysSafe')}</p></div><div className="connected"><Wifi size={15} /> {t('internetConnected')}</div></div><div className="sync-hero"><Cloud size={28} /><div><strong>{p.syncing ? t('syncingRecords') : t('assessmentsWaiting')}</strong><span>{p.syncing ? t('validatingRecords') : t('savedLocally')}</span></div><button className="primary-button" onClick={p.onSync}>{p.syncing ? t('syncing') : t('syncNow')} <Cloud size={16} /></button></div><div className="stat-grid"><Card><span className="stat-label">{t('pending')}</span><strong>{p.syncing ? 2 : 3}</strong><small>{t('offlineRecords')}</small></Card><Card><span className="stat-label">{t('syncedToday')}</span><strong>9</strong><small className="positive">{t('allRecordsSafe')}</small></Card><Card><span className="stat-label">{t('lastSyncLabel')}</span><strong className="time-stat">4:32</strong><small>{t('todayPM')}</small></Card></div></div> }
function Profile(p: any) { const { t, district } = useLang(); return <div className="content"><StepHead kicker={t('fieldWorkerAccount')} title={t('myProfile')} copy={t('profileCopy')} /><Card className="profile-card"><div className="worker-avatar">{t('initialsWorker')}</div><h2>{t('workerName')}</h2><p className="muted">{t('workerRole')}</p><div className="case-details"><span>{t('workerId')} <b>ASHA-2048</b></span><span>{t('district')} <b>{district('beed')}</b></span><span>{t('language')} <LanguageMenu /></span></div><button className="outline-button" onClick={() => p.notify(t('profileEditing'))}>{t('editProfile')}</button><button className="outline-button" onClick={() => p.notify(t('settingsOpened'))}>{t('settings')} <Settings size={15} /></button></Card></div> }

function PortalApp(p: any) { const { t } = useLang(); const nav = [{ n: 'Overview', label: t('overview'), i: Home }, { n: 'Priority Cases', label: t('priorityCases'), i: AlertTriangle }, { n: 'Patients', label: t('patients'), i: Users }, { n: 'Screening Analytics', label: t('screeningAnalytics'), i: LineChart }, { n: 'District Map', label: t('districtMap'), i: MapPin }, { n: 'Referrals', label: t('referrals'), i: Send }, { n: 'Settings', label: t('settings'), i: Settings }]; return <><aside className={`portal-sidebar ${p.doctorMenuOpen ? 'mobile-open' : ''}`}><Brand compact /><div className="portal-user"><div className="doctor-avatar">{t('initialsDoctor')}</div><div><strong>{t('doctorName')}</strong><span>{t('doctorRole')}</span></div></div><nav>{nav.map(({ n, label, i: I }) => <button className={p.section === n ? 'active' : ''} onClick={() => { n === 'Settings' ? p.notify(t('settingsOpened')) : p.setSection(n); p.setDoctorMenuOpen(false) }} key={n}><I size={17} />{label}{n === 'Priority Cases' && <b>2</b>}</button>)}</nav><div className="sidebar-footer"><div><span className="live-dot" /> {t('dataSystems')}</div><small>{t('demoWorkspace')}</small><button className="portal-logout" onClick={p.requestLogout}><LogOut size={17} /> {t('logout')}</button></div></aside><main className="portal-main">{p.doctorMenuOpen && <button className="mobile-backdrop" aria-label={t('closeMenu')} onClick={() => p.setDoctorMenuOpen(false)} /> }<div className="mobile-header doctor-mobile-header"><button className="menu-trigger" aria-label={t('openMenu')} onClick={() => p.setDoctorMenuOpen((open: boolean) => !open)}><Menu /></button><Brand compact /><span style={{ marginRight: 10 }}><LanguageMenu /></span><div className="avatar">{t('initialsDoctor')}</div></div><header className="portal-header"><div><span className="eyebrow">{t('clinicalPortal')}</span><h1>{p.section === 'Priority Cases' ? t('titlePriority') : p.section === 'Patients' ? t('titleRegistry') : p.section === 'Screening Analytics' ? t('titleAnalytics') : p.section === 'District Map' ? t('titleSurveillance') : p.section === 'Referrals' ? t('titleReferrals') : t('titleClinical')}</h1></div><div className="portal-actions"><button className="outline-button" onClick={() => p.notify(t('reportExported'))}><Download size={15} /> {t('exportReport')}</button><button className="avatar" aria-label={t('openLogoutConfirm')} onClick={p.requestLogout}>{t('initialsDoctor')}</button></div></header>{p.section === 'Priority Cases' ? <Queue {...p} /> : p.section === 'Patients' ? <PatientRegistry {...p} /> : p.section === 'Screening Analytics' ? <ScreeningAnalytics {...p} /> : p.section === 'District Map' ? <AnalyticsView {...p} /> : p.section === 'Referrals' ? <ReferralManagement {...p} /> : <Dashboard {...p} />}</main></> }
function Metric({ label, value, delta, icon: Icon, tone }: any) { return <button className="metric-card card" onClick={() => {}}><div className={`metric-icon ${tone || ''}`}><Icon size={18} /></div><span>{label}</span><strong>{value}</strong><small>{delta}</small></button> }
function Dashboard(p: any) { const { t, tf, risk } = useLang(); const high = p.patients.filter((x: Patient) => x.risk === 'High').length; const totalScreened = 12482 + p.patients.length - 5; return <div className="portal-content"><div className="metrics-row"><Metric label={t('totalScreened')} value={totalScreened.toLocaleString()} delta="↑ 12.4%" icon={Users} /><Metric label={t('highRisk')} value={(MAHARASHTRA_TOTALS.high + high - 2).toLocaleString()} delta={tf('ofTotal', { p: '9.2%' })} icon={AlertTriangle} tone="red" /><Metric label={t('moderateRisk')} value="3,872" delta={tf('ofTotal', { p: '31.0%' })} icon={Activity} tone="amber" /><Metric label={t('lowRisk')} value="7,464" delta={tf('ofTotal', { p: '59.8%' })} icon={Check} tone="green" /></div><div className="portal-grid"><Card className="chart-card"><div className="card-heading"><div><span className="eyebrow">{t('regionLast30')}</span><h3>{t('screeningActivity')}</h3></div><LineChart /></div><div className="big-chart"><div className="chart-y"><span>600</span><span>400</span><span>200</span><span>0</span></div><svg viewBox="0 0 700 230" preserveAspectRatio="none" role="img" aria-label={t('screeningActivity')}><path className="area" d="M0 196 C60 170 70 180 115 140 S180 160 230 112 S290 126 335 105 S400 139 445 73 S510 98 555 52 S620 100 700 24 L700 230 L0 230Z" /><path className="line" d="M0 196 C60 170 70 180 115 140 S180 160 230 112 S290 126 335 105 S400 139 445 73 S510 98 555 52 S620 100 700 24" /></svg></div></Card><Card className="distribution-card"><div className="card-heading"><div><span className="eyebrow">{t('currentCohort')}</span><h3>{t('oaRiskDistribution')}</h3></div><BarChart3 /></div><div className="donut-wrap"><div className="donut">
  <strong>{totalScreened.toLocaleString('en-IN')}</strong>
  <span>{t('screened')}</span>
</div><div className="legend"><span>{risk('Low')} <b>59.8%</b></span><span>{risk('Moderate')} <b>31.0%</b></span><span>{risk('High')} <b>9.2%</b></span></div></div></Card></div><div className="section-title portal-section"><h2>{t('priorityCasesHeading')}</h2><button className="text-button" onClick={() => p.setSection('Priority Cases')}>{t('viewQueue')} <ArrowRight size={15} /></button></div><QueueTable {...p} /></div> }
function QueueTable(p: any) { const { t, tf, L, status, risk, district } = useLang(); const [query, setQuery] = useState(''); const rows = p.patients.filter((x: Patient) => (x.risk === 'High') && nameText(x).toLowerCase().includes(query.toLowerCase())); return <Card className="queue-card"><div className="table-toolbar"><div className="search-box"><Search size={15} /><input placeholder={t('searchPatientsShort')} aria-label={t('searchPatientsShort')} value={query} onChange={(e) => setQuery(e.target.value)} /></div><Badge risk="High">{tf('highRiskCount', { n: rows.length })}</Badge></div><div className="table-wrap"><table><thead><tr><th>{t('colPatient')}</th><th>{t('colAge')}</th><th>{t('colDistrict')}</th><th>{t('colRiskScore')}</th><th>{t('colROM')}</th><th>{t('colGait')}</th><th>{t('colStatus')}</th><th /></tr></thead><tbody>{rows.map((x: Patient) => <tr key={x.name}><td><strong>{L(x.nameL)}</strong><small>{L(x.villageL)}</small></td><td>{x.age}</td><td>{district(x.district)}</td><td><span className="table-score risk-high">{x.score}</span></td><td>{x.rom}</td><td>{x.gait}</td><td><Badge risk={x.risk}>{status(x.status)}</Badge></td><td><button className="review-button" onClick={() => { p.setSelected(x); p.setSection('Patients') }}>{t('reviewBtn')}</button></td></tr>)}</tbody></table>{!rows.length && <div className="empty-state">{t('noPatientsFound')}</div>}</div></Card> }
function Queue(p: any) { const { t, tf } = useLang(); return <div className="portal-content"><div className="queue-callout"><AlertTriangle size={20} /><div><strong>{tf('needClinicalReview', { n: p.patients.filter((x: Patient) => x.risk === 'High').length })}</strong><span>{t('prioritizedBySimulated')}</span></div><Badge risk="High">{t('actionRecommended')}</Badge></div><QueueTable {...p} /></div> }
function PatientRegistry(p: any) { const { t, L, riskPhrase, pain, occupation } = useLang(); return <div className="portal-content"><div className="registry-summary"><Card><Users size={19} /><strong>{(12482 + p.patients.length - 5).toLocaleString()}</strong><span>{t('registeredPatients')}</span></Card><Card><Activity size={19} /><strong>146</strong><span>{t('awaitingFollowUp')}</span></Card><Card><Cloud size={19} /><strong>98.6%</strong><span>{t('recordsSynced')}</span></Card></div><QueueTable {...p} />{p.selected && <Card className="clinical-drawer"><button aria-label={t('close')} onClick={() => p.setSelected(null)}><X size={17} /></button><span className="eyebrow">{t('clinicalCaseReview')}</span><h2>{L(p.selected.nameL)}</h2><div className="case-risk"><Badge risk={p.selected.risk}>{riskPhrase(p.selected.risk)}</Badge><strong>{p.selected.score}<small>/100</small></strong></div><div className="case-details"><span>{t('age')} <b>{p.selected.age}</b></span><span>{t('bmi')} <b>{PATIENT_DETAILS[p.selected.name]?.bmi.toFixed(1)}</b></span><span>{t('occupation')} <b>{occupation(p.selected.occupation)}</b></span><span>{t('pain')} <b>{pain(p.selected.pain)}</b></span></div><h3>{t('whyFlagged')}</h3><div className="explain"><span>{t('reducedROM')}</span><div><i style={{ width: '88%' }} /></div><b>88%</b></div><div className="explain"><span>{t('gaitAsymmetry')}</span><div><i style={{ width: '72%' }} /></div><b>72%</b></div><p className="insight"><Sparkles size={16} /> {t('drawerInsight')}</p><div className="drawer-actions"><button className="primary-button" onClick={() => p.notify(t('referralFormOpened'))}>{t('createReferral')} <ArrowRight size={15} /></button><button className="outline-button" onClick={() => p.notify(t('patientMarkedReviewed'))}>{t('markReviewed')}</button></div></Card>}</div> }
function ScreeningAnalytics(p: any) { const { t, tf, risk, period: periodLabel, district: districtName } = useLang(); const [period, setPeriod] = useState('90 days'); const [riskFilter, setRisk] = useState('All'); const [district, setDistrict] = useState('all'); const records = p.patients.filter((x: Patient) => (riskFilter === 'All' || x.risk === riskFilter) && (district === 'all' || x.district === district)); const counts = { Low: records.filter((x: Patient) => x.risk === 'Low').length, Moderate: records.filter((x: Patient) => x.risk === 'Moderate').length, High: records.filter((x: Patient) => x.risk === 'High').length }; const districtIds = Array.from(new Set<string>(p.patients.map((x: Patient) => x.district))); return <div className="portal-content"><div className="analytics-toolbar"><div><span className="eyebrow">{t('regionUpdatedToday')}</span><h2>{t('screeningPerformance')}</h2></div><div className="analytics-filters"><select aria-label={t('timePeriod')} value={period} onChange={(e) => setPeriod(e.target.value)}>{['30 days', '90 days', '12 months'].map((x) => <option key={x} value={x}>{periodLabel(x)}</option>)}</select><select aria-label={t('district')} value={district} onChange={(e) => setDistrict(e.target.value)}><option value="all">{t('allDistricts')}</option>{districtIds.map((x) => <option key={x} value={x}>{districtName(x)}</option>)}</select><select aria-label={t('riskWord')} value={riskFilter} onChange={(e) => setRisk(e.target.value)}><option value="All">{t('all')}</option><option value="Low">{risk('Low')}</option><option value="Moderate">{risk('Moderate')}</option><option value="High">{risk('High')}</option></select></div></div><div className="metrics-row"><Metric label={t('filteredScreenings')} value={records.length} delta={tf('periodView', { period: periodLabel(period) })} icon={Activity} /><Metric label={t('highRisk')} value={counts.High} delta={t('needsReview')} icon={AlertTriangle} tone="red" /><Metric label={t('moderateRisk')} value={counts.Moderate} delta={t('monitorClosely')} icon={Activity} tone="amber" /><Metric label={t('lowRisk')} value={counts.Low} delta={t('routineFollowUp')} icon={Check} tone="green" /></div><div className="analytics-grid"><Card className="chart-card"><div className="card-heading"><div><span className="eyebrow">{t('screeningsByWeek')}</span><h3>{t('activityTrend')}</h3></div><LineChart /></div><div className="big-chart analytics-chart"><div className="chart-y"><span>40</span><span>30</span><span>20</span><span>0</span></div><svg viewBox="0 0 700 230" preserveAspectRatio="none" role="img" aria-label={t('activityTrend')}><path className="area" d="M0 192 C80 170 100 180 160 132 S250 150 310 92 S410 128 470 72 S570 105 700 30 L700 230 L0 230Z" /><path className="line" d="M0 192 C80 170 100 180 160 132 S250 150 310 92 S410 128 470 72 S570 105 700 30" /></svg></div></Card><Card className="distribution-card"><div className="card-heading"><div><span className="eyebrow">{t('filteredCohort')}</span><h3>{t('riskDistribution')}</h3></div><BarChart3 /></div><div className="risk-distribution"><div className="risk-bar-row"><span>{risk('High')}</span><i className="red-bar" style={{ width: `${records.length ? counts.High / records.length * 100 : 0}%` }} /><b>{counts.High}</b></div><div className="risk-bar-row"><span>{risk('Moderate')}</span><i className="amber-bar" style={{ width: `${records.length ? counts.Moderate / records.length * 100 : 0}%` }} /><b>{counts.Moderate}</b></div><div className="risk-bar-row"><span>{risk('Low')}</span><i className="green-bar" style={{ width: `${records.length ? counts.Low / records.length * 100 : 0}%` }} /><b>{counts.Low}</b></div></div></Card></div><Card className="analytics-table-card"><div className="card-heading"><div><span className="eyebrow">{t('districtBreakdown')}</span><h3>{t('coverageAndRisk')}</h3></div><Badge>{tf('recordsCount', { n: records.length })}</Badge></div><div className="table-wrap"><table><thead><tr><th>{t('colDistrict')}</th><th>{t('colScreened')}</th><th>{t('colHighRisk')}</th><th>{t('colAvgScore')}</th></tr></thead><tbody>{districtIds.map((id) => { const rows = records.filter((x: Patient) => x.district === id); return <tr key={id}><td><strong>{districtName(id)}</strong></td><td>{rows.length}</td><td><Badge risk="High">{rows.filter((x: Patient) => x.risk === 'High').length}</Badge></td><td>{rows.length ? Math.round(rows.reduce((sum: number, x: Patient) => sum + x.score, 0) / rows.length) : 0}/100</td></tr> })}</tbody></table></div></Card></div> }

function ReferralManagement(p: any) { const { t, tf, L, risk, referral, district } = useLang(); const [query, setQuery] = useState(''); const [status, setStatus] = useState('All'); const rows = p.referrals.filter((x: any) => (status === 'All' || x.referralStatus === status) && nameDistrictText(x).includes(query.toLowerCase())); const statuses = ['Pending', 'In review', 'Completed']; return <div className="portal-content"><div className="page-heading"><div><span className="eyebrow">{tf('careCoordination', { n: p.referrals.length })}</span><h2>{t('referralMgmtHeading')}</h2><p className="muted">{t('trackHandoffs')}</p></div><button className="primary-button" onClick={() => p.notify(t('referralFormOpened'))}><Plus size={16} /> {t('newReferral')}</button></div><div className="registry-summary"><Card><Send size={19} /><strong>{p.referrals.length}</strong><span>{t('totalReferrals')}</span></Card><Card><AlertTriangle size={19} /><strong>{p.referrals.filter((x: any) => x.referralStatus === 'Pending').length}</strong><span>{t('pendingReview')}</span></Card><Card><Check size={19} /><strong>{p.referrals.filter((x: any) => x.referralStatus === 'Completed').length}</strong><span>{t('refCompleted')}</span></Card></div><Card className="referral-card"><div className="table-toolbar"><div className="search-box"><Search size={15} /><input placeholder={t('searchReferrals')} aria-label={t('searchReferrals')} value={query} onChange={(e) => setQuery(e.target.value)} /></div><select aria-label={t('colStatus')} value={status} onChange={(e) => setStatus(e.target.value)}><option value="All">{t('all')}</option>{statuses.map((x) => <option key={x} value={x}>{referral(x)}</option>)}</select></div><div className="table-wrap"><table><thead><tr><th>{t('colPatient')}</th><th>{t('colDistrict')}</th><th>{t('colRisk')}</th><th>{t('colReferredOn')}</th><th>{t('colStatus')}</th><th /></tr></thead><tbody>{rows.map((x: any) => <tr key={x.name}><td><strong>{L(x.nameL)}</strong><small>{tf('ageYears', { n: x.age })} · {L(x.villageL)}</small></td><td>{district(x.district)}</td><td><Badge risk={x.risk}>{risk(x.risk)}</Badge></td><td>{t('dateReferred')}</td><td><select className="status-select" aria-label={t('colStatus')} value={x.referralStatus} onChange={(e) => p.setReferrals((old: any[]) => old.map((item) => item.name === x.name ? { ...item, referralStatus: e.target.value } : item))}>{statuses.map((s) => <option key={s} value={s}>{referral(s)}</option>)}</select></td><td><button className="review-button" onClick={() => { p.setSelected(x); p.setSection('Patients') }}>{t('reviewBtn')}</button></td></tr>)}</tbody></table>{!rows.length && <div className="empty-state">{t('noReferrals')}</div>}</div></Card></div> }

function AnalyticsView(p: any) { const { t, tf, risk, district } = useLang(); const [state, setState] = useState(DISTRICTS[0].id); const mapDistricts = [['s1', 'beed'], ['s2', 'kolhapur'], ['s3', 'gadchiroli'], ['s4', 'yavatmal'], ['s5', 'solapur'], ['s6', 'ratnagiri'], ['s7', 'nandurbar']]; return <div className="portal-content"><div className="analytics-filters"><select aria-label={t('district')} value={state} onChange={(e) => setState(e.target.value)}>{DISTRICTS.map((d) => <option key={d.id} value={d.id}>{district(d.id)}</option>)}</select><button onClick={() => p.notify(t('districtFilterOpened'))}>{t('allDistricts')} <ChevronDown size={13} /></button><button onClick={() => p.notify(t('timePeriodUpdated'))}>{t('last90Days')} <ChevronDown size={13} /></button></div><div className="analytics-grid"><Card className="map-card"><div className="card-heading"><div><span className="eyebrow">{t('simulatedSurveillance')}</span><h3>{t('districtSurveillance')}</h3></div><MapPin /></div><div className="map-visual"><div className="map-shape">{mapDistricts.map(([cls, id]) => <button key={id} className={`state ${cls}`} onClick={() => setState(id)}>{district(id)}</button>)}</div></div></Card><Card className="district-card"><span className="eyebrow">{t('selectedDistrict')}</span><h3>{district(state)}</h3><div className="district-number">1,842 <small>{t('screened')}</small></div><div className="district-bars"><div><span>{t('highRisk')} <b>17.8%</b></span><i className="red-bar" style={{ width: '56%' }} /></div><div><span>{t('moderateRisk')} <b>34.2%</b></span><i className="amber-bar" style={{ width: '78%' }} /></div><div><span>{t('lowRisk')} <b>48.0%</b></span><i className="green-bar" style={{ width: '92%' }} /></div></div><button className="primary-button full" onClick={() => p.notify(tf('districtDetailSelected', { district: district(state) }))}>{t('openDistrictDetail')} <ArrowRight size={15} /></button></Card></div></div> }

export { Brand }
